    "            {id: '$($_.Nombre)', label: '$($_.Nombre)\n[$($_.Tipo)]', color: '$color', title: 'Salud: $($_.ScoreSalud)%<br>Deuda: $($_.DeudaTecnica)%<br>Líneas: $($_.Analisis.LineasCodigo)'}"
